import React from 'react';

export default function BlogComponent() {
    return(
        <div className="container">
            <div className="section-header">
                <h1>
                    <span className="prompt">❯ </span>ls ./blog
                </h1>
            </div>
            <div className="blog-placeholder">
                <h2><span className="comment">// </span>Coming Soon</h2>
                <p>
                    <span className="prompt">❯ </span>
                    <span className="command">echo </span>
                    <span className="string">"Posts about performance engineering, systems, and dev life — brewing..."</span>
                </p>
            </div>
        </div>
    );
}
